## 四、完整的实例（基于 ESP32 + DHT22）

> 下面的代码展示了 **滑动平均 + 最小运行/停机时间 + 阈值 + 继电器控制**，可直接烧写到 ESP32，配合 Arduino IDE。

```ino
#include <WiFi.h>
#include <PubSubClient.h>
#include <DHT.h>

#define DHTPIN 4
#define DHTTYPE DHT22
DHT dht(DHTPIN, DHTTYPE);

const int AC_RELAY_PIN = 5;          // 继电器控制（低电平触发）

// 参数配置
const float TEMP_ON   = 28.0;        // 开空调阈值
const float TEMP_OFF  = 24.0;        // 关空调阈值
const unsigned long MIN_ON_MS   = 5*60*1000;  // 5 min
const unsigned long MIN_OFF_MS  = 5*60*1000;  // 5 min

bool acState = false;               // 当前空调状态
unsigned long lastOnMs  = 0;
unsigned long lastOffMs = 0;

// 滑动平均缓冲（最近 30 次采样）
const int AVG_SIZE = 30;
float tempBuffer[AVG_SIZE];
int bufIdx = 0;
unsigned long lastSampleMs = 0;
const unsigned long SAMPLE_INTERVAL_MS = 2000; // 每 2 s 采样一次

// Wi‑Fi & MQTT（可自行填入）
const char* ssid = "YOUR_SSID";
const char* password = "YOUR_PASSWORD";
const char* mqtt_server = "broker.hivemq.com";
WiFiClient espClient;
PubSubClient client(espClient);

void setup() {
    Serial.begin(115200);
    dht.begin();
    pinMode(AC_RELAY_PIN, OUTPUT);
    digitalWrite(AC_RELAY_PIN, HIGH); // 继电器默认关闭

    WiFi.begin(ssid, password);
    while (WiFi.status() != WL_CONNECTED) delay(500);
    client.setServer(mqtt_server, 1883);
}

void loop() {
    unsigned long now = millis();

    // 1. 采样 & 滑动平均
    if (now - lastSampleMs >= SAMPLE_INTERVAL_MS) {
        float t = dht.readTemperature();
        if (!isnan(t)) {
            tempBuffer[bufIdx++] = t;
            if (bufIdx >= AVG_SIZE) bufIdx = 0;
        }
        lastSampleMs = now;
    }

    // 2. 计算平均
    float avgTemp = 0;
    for (int i = 0; i < AVG_SIZE; i++) avgTemp += tempBuffer[i];
    avgTemp /= AVG_SIZE;

    // 3. 控制逻辑
    if (!acState) { // 关机状态
        if (avgTemp >= TEMP_ON && (now - lastOffMs >= MIN_OFF_MS)) {
            digitalWrite(AC_RELAY_PIN, LOW); // 开空调
            acState = true;
            lastOnMs = now;
            Serial.println("AC ON");
        }
    } else { // 开机状态
        if (avgTemp <= TEMP_OFF && (now - lastOnMs >= MIN_ON_MS)) {
            digitalWrite(AC_RELAY_PIN, HIGH); // 关空调
            acState = false;
            lastOffMs = now;
            Serial.println("AC OFF");
        }
    }

    // 4. MQTT 上报（可选）
    if (!client.connected()) {
        client.connect("esp32_ac");
    }
    client.loop();
    char msg[50];
    snprintf(msg, sizeof(msg), "{\"temp\":%.1f,\"ac\":%s}",
             avgTemp, acState ? "on" : "off");
    client.publish("home/ac/status", msg);

    delay(100);
}
```

### 关键点解释

| 块 | 说明 |
|----|------|
| **滑动平均** | `tempBuffer` 保存最近 30 次读数，避免一次瞬时突变导致误判。 |
| **最小开关时间** | `MIN_ON_MS`、`MIN_OFF_MS` 确保每次开/关至少维持 5 min。 |
| **阈值** | 28 °C 开、24 °C 关（可自行调节）。 |
| **继电器** | 低电平触发（常开），打开时 `digitalWrite(LOW)`。 |
| **MQTT** | 可把状态发送到 Home Assistant，实现远程监控。 |

